  "collection.airline.title": "Airline & Travel",
  "collection.airline.desc":
    "Flight & airline stack — passenger side (flight search, results list, seat-map selector, booking flow, online check-in, mobile boarding pass, flight status board, multi-leg itinerary, frequent-flyer card, baggage tracker), airport/staff (gate departure display, FIDS board, gate-agent boarding, self-check-in kiosk), marketing pages (airline landing, destinations, fleet, loyalty), ops/admin (control center, crew schedule, load-factor report), and five themed airline landings (legacy carrier, low-cost, premium boutique, regional, private charter). Aviation blue + cloud white + sunrise orange, clean grotesque, precise iconography, large status indicators.",
  "collection.cowork.title": "Coworking & Studio Rental",
  "collection.cowork.desc":
    "Workspace booking & community stack — member side (desk booking, meeting-room booking, member dashboard, mobile access card/QR, credits/hours balance, community feed), operations/front desk (live floor plan with occupancy, visitor check-in kiosk, equipment status), marketing pages (landing, spaces/tour, membership pricing, events), admin (occupancy & utilization dashboard, billing & subscriptions), and five themed landings (creative loft, corporate flex, maker space, café-style, suburban hub). Warm concrete + amber + matte black, modern sans, industrial photography, plant accents.",
  "collection.auto.title": "Auto Repair & Dealership",
