  "home.manifesto.practiceBody":
    "Anda dapat versi pertama yang lebih pantas, rujukan pelaksanaan yang lebih kukuh, dan kurang permulaan buntu. Daripada menjahit konteks daripada sepuluh sumber berbeza, anda bekerja dari satu tempat dan bergerak dengan niat yang jelas.",
  "home.manifesto.outcomesAria": "Hasil praktikal",
  "home.manifesto.outcomeA.accent": "Kelajuan dengan kawalan:",
  "home.manifesto.outcomeA.text":
    "mulakan daripada asas sebenar dan kekalkan standard anda sendiri.",
  "home.manifesto.outcomeB.accent": "Bahasa bersama:",
  "home.manifesto.outcomeB.text": "manusia dan bot boleh berfikir daripada rujukan yang sama.",
  "home.manifesto.outcomeC.accent": "Pengetahuan yang terkumpul:",
  "home.manifesto.outcomeC.text": "setiap penggunaan semula memudahkan binaan seterusnya.",
  "home.manifesto.future":
    "Arah masa depan: sistem visual tersuai, tetapan aliran kerja tersuai, dan penciptaan perisian dari mana-mana sahaja mengikut peraturan anda sendiri.",
  "home.roadmap.eyebrow": "Peta jalan sedang berjalan",
  "home.roadmap.title": "Dari asas ke rangka kerja web berteraskan AI",
  "home.roadmap.lead":
    "Kami membinanya secara terbuka, langkah demi langkah. Laluan ini bermula dengan asas yang kukuh, kemudian kualiti dokumentasi, kemudian aliran kerja penjanaan projek, dan akhirnya rangka kerja ringan untuk membina perisian web dengan sokongan AI.",
  "home.roadmap.dot.foundation": "Asas",
  "home.roadmap.dot.docs": "Kualiti dokumen",
  "home.roadmap.dot.builder": "Pembina",
  "home.roadmap.dot.framework": "Rangka kerja",
  "home.roadmap.phase1.title": "Bina asas",
  "home.roadmap.phase1.body":
    "Menstabilkan seni bina asas, halaman teras, primitif boleh guna semula, dan bahasa visual.",
  "home.roadmap.phase2.title": "Tingkatkan dokumen dengan amalan terbaik",
  "home.roadmap.phase2.body":
    "Jadikan panduan lebih jelas, praktikal, dan boleh terus digunakan supaya orang boleh melaksana lebih cepat dengan kurang kekeliruan.",
  "home.roadmap.phase3.title": "Perbaiki builder untuk penciptaan projek",
  "home.roadmap.phase3.body":
    "Kurangkan geseran persediaan dan jadikan scaffolding projek lebih terkawal berasaskan rujukan.",
  "home.roadmap.phase4.title": "Cipta rangka kerja asas StealThis",
  "home.roadmap.phase4.body":
    "Rangka kerja ringkas untuk projek web, diinspirasikan oleh aliran kerja gaya Astro dan berfokus pada penciptaan berbantu AI.",
  "home.keywords.eyebrow": "Bahasa projek",
  "home.keywords.title": "Perkataan yang mentakrifkan projek ini",
  "home.keywords.lead":
    "Ini bukan istilah pemasaran. Ini ialah prinsip operasi untuk cara kami membina, berkongsi, dan melancarkan perisian dengan kurang kerumitan dan lebih pemilikan.",
  "home.keywords.aria": "Kata kunci projek dan maknanya",
  "home.keywords.control.word": "KAWALAN",
  "home.keywords.control.accent": "Kawalan",
  "home.keywords.control.text":
    "bermaksud memilih stack, sistem gaya, dan rentak penghantaran anda tanpa terkunci pada lalai yang kaku.",
  "home.keywords.reference.word": "RUJUKAN",
  "home.keywords.reference.accent": "Rujukan",
  "home.keywords.reference.text":
    "bermaksud belajar daripada pelaksanaan konkrit, bukan daripada perbincangan abstrak yang bersepah di sumber yang terpisah.",
  "home.keywords.reuse.word": "GUNA SEMULA",
  "home.keywords.reuse.accent": "Guna semula",
  "home.keywords.reuse.text":
    "ialah lalai. Mulakan daripada asas terbukti, sesuaikan, dan gunakan tenaga pada pembezaan bukan pengulangan.",
  "home.keywords.collaboration.word": "KOLABORASI",
  "home.keywords.collaboration.accent": "Kolaborasi",
  "home.keywords.collaboration.text":
    "bermaksud manusia dan bot membina daripada konteks, konvensyen, dan rujukan produksi yang sama.",
  "home.keywords.practice.word": "AMALAN",
  "home.keywords.practice.accent": "Amalan",
  "home.keywords.practice.text":
    "ialah tempat kualiti muncul: aliran kerja yang boleh diulang, corak yang diuji, dan disiplin pelaksanaan.",
  "home.keywords.ownership.word": "PEMILIKAN",
  "home.keywords.ownership.accent": "Pemilikan",
  "home.keywords.ownership.text":
    "bermaksud memahami apa yang anda jalankan, mengapa ia berfungsi, dan bagaimana mengembangkannya apabila keperluan berubah.",
  "home.keywords.clarity.word": "KEJELASAN",
  "home.keywords.clarity.accent": "Kejelasan",
  "home.keywords.clarity.text":
    "menghapuskan geseran: satu tempat untuk rujukan, satu bahasa untuk keputusan, satu laluan dari idea ke penghantaran.",
  "home.keywords.ship.word": "LANCAR",
  "home.keywords.ship.accent": "Lancar",
  "home.keywords.ship.text":
    "bermaksud sampai ke produksi lebih awal tanpa menurunkan standard seni bina, kebolehcapaian, dan kebolehselenggaraan.",
  "home.scramble.eyebrow": "Falsafah Steal This",
  "home.scramble.title": "Perkataan yang kami dedahkan ketika membina",
  "home.scramble.lead":
    "Setiap baris di bawah ialah komitmen kepada cara membina perisian yang lebih praktikal: rujukan yang berpijak di bumi, konteks bersama, dan pelaksanaan yang lebih pantas dengan kawalan.",
  "home.scramble.phrases":
    "STEAL THIS ->||BINA DENGAN KAWALAN||MULAKAN DENGAN RUJUKAN||MANUSIA + BOT||KURANG GESEKAN, LEBIH CEPAT LANCAR",
