    "사람과 봇이 같은 맥락, 관례, 프로덕션 레퍼런스에서 함께 빌드하는 것을 뜻합니다.",
  "home.keywords.practice.word": "실천",
  "home.keywords.practice.accent": "실천",
  "home.keywords.practice.text":
    "품질이 드러나는 지점입니다. 반복 가능한 워크플로, 검증된 패턴, 구현 규율이 여기에 있습니다.",
  "home.keywords.ownership.word": "소유권",
  "home.keywords.ownership.accent": "소유권",
  "home.keywords.ownership.text":
    "무엇을 운영하는지, 왜 동작하는지, 요구사항이 바뀔 때 어떻게 진화시킬지 이해하는 것을 뜻합니다.",
  "home.keywords.clarity.word": "명확성",
  "home.keywords.clarity.accent": "명확성",
  "home.keywords.clarity.text":
    "마찰을 제거합니다. 레퍼런스를 위한 한 장소, 결정을 위한 한 언어, 아이디어에서 전달까지 한 경로를 만듭니다.",
  "home.keywords.ship.word": "출시",
  "home.keywords.ship.accent": "출시",
  "home.keywords.ship.text":
    "아키텍처, 접근성, 유지보수성 기준을 낮추지 않고 더 빨리 프로덕션에 도달하는 것을 뜻합니다.",
  "home.scramble.eyebrow": "Steal This 철학",
  "home.scramble.title": "빌드하면서 드러내는 단어들",
  "home.scramble.lead":
    "아래의 모든 문장은 더 실용적인 소프트웨어 제작 방식에 대한 약속입니다. 단단한 레퍼런스, 공유된 맥락, 그리고 통제력을 갖춘 더 빠른 실행이 핵심입니다.",
