  "collection.saas.title": "SaaS 빌더",
  "collection.saas.desc": "랜딩 페이지, 대시보드, SaaS 아키텍처 레퍼런스.",
  "collection.motion.title": "모션 에센셜",
  "collection.motion.desc": "모던 UI를 위한 스크롤·리빌 애니메이션.",
  "collection.hero.title": "히어로 스타터",
  "collection.hero.desc": "히어로 섹션, CTA 블록, 랜딩 레이아웃.",
  "collection.cards.title": "카드 컴포넌트",
