  "collection.music.desc": "Künstler- und Albumseiten, synchronisierte Lyrics, Tourdaten, ein wiederverwendbares Playback-Toolkit (Player-Bar, Vollbild-Now-Playing, Waveform, Equalizer, Warteschlange), Discovery- und Profilansichten, ein Künstler-Dashboard und thematische Vinyl-/Streaming-/Festival-/Klassik-/Hip-Hop-Landingpages.",
