  "home.manifesto.eyebrow": "Costruisci con controllo",
  "home.manifesto.title": "Prendi ciò che funziona. Rilascia ciò che vuoi.",
  "home.manifesto.lead": "Per umani e bot che vogliono creare software senza partire da zero.",
  "home.manifesto.body1":
    "StealThis è una libreria orientata ai riferimenti. Analizza ogni elemento, capisci come funziona e riusalo nel tuo stack. Meno frammentazione, meno complessità e più controllo sul sistema di stile e sugli strumenti con cui vuoi costruire.",
  "home.manifesto.body2":
    "L'obiettivo è semplice: un luogo collaborativo dove convivono conoscenza, pratiche collaudate e riferimenti pronti per la produzione. Scegli una base, la adatti e vai avanti senza ricostruire i fondamentali ogni volta.",
  "home.manifesto.howToTitle": "Come usare questo spazio",
  "home.manifesto.howToAria": "Come usare questo spazio",
  "home.manifesto.step1.accent": "Trova un riferimento",
  "home.manifesto.step1.text": "che risolve già parte del tuo problema.",
  "home.manifesto.step2.accent": "Studialo rapidamente:",
  "home.manifesto.step2.text": "struttura, comportamento e dettagli di implementazione.",
  "home.manifesto.step3.accent": "Adattalo",
  "home.manifesto.step3.text": "al tuo sistema di stile, stack e vincoli.",
  "home.manifesto.step4.accent": "Rilascia prima",
  "home.manifesto.step4.text": "senza sacrificare la qualità del codice.",
  "home.manifesto.micro": "Meno boilerplate. Meno cambio di contesto. Più costruzione.",
  "home.manifesto.practiceTitle": "Cosa ottieni nella pratica",
  "home.manifesto.practiceBody":
    "Ottieni una prima versione più veloce, riferimenti di implementazione più solidi e meno false partenze. Invece di cucire contesto da dieci fonti diverse, lavori da un unico posto e procedi con intenzione.",
  "home.manifesto.outcomesAria": "Risultati pratici",
  "home.manifesto.outcomeA.accent": "Velocità con controllo:",
  "home.manifesto.outcomeA.text": "parti da una base reale e mantieni i tuoi standard.",
  "home.manifesto.outcomeB.accent": "Linguaggio condiviso:",
  "home.manifesto.outcomeB.text": "umani e bot ragionano sugli stessi riferimenti.",
  "home.manifesto.outcomeC.accent": "Conoscenza cumulativa:",
  "home.manifesto.outcomeC.text": "ogni riuso rende più facile la build successiva.",
  "home.manifesto.future":
    "Direzione futura: sistemi visivi personalizzati, setup di workflow personalizzati e creazione software da ovunque con le tue regole.",
  "home.roadmap.eyebrow": "Roadmap in corso",
  "home.roadmap.title": "Dalle fondamenta a un framework web AI-first",
  "home.roadmap.lead":
    "Stiamo costruendo in pubblico, passo dopo passo. Il percorso parte da fondamenta solide, poi qualità della documentazione, poi workflow di generazione progetti e infine un framework leggero per costruire software web con supporto AI.",
  "home.roadmap.dot.foundation": "Fondamenta",
  "home.roadmap.dot.docs": "Qualità docs",
  "home.roadmap.dot.builder": "Builder",
  "home.roadmap.dot.framework": "Framework",
  "home.roadmap.phase1.title": "Costruire le fondamenta",
  "home.roadmap.phase1.body":
    "Stabilizzare architettura base, pagine core, primitive riutilizzabili e linguaggio visivo.",
  "home.roadmap.phase2.title": "Migliorare docs con best practice",
  "home.roadmap.phase2.body":
    "Rendere le guide più chiare, pratiche e azionabili per implementare più velocemente con meno confusione.",
  "home.roadmap.phase3.title": "Migliorare il builder per creare progetti",
  "home.roadmap.phase3.body":
    "Ridurre la frizione di setup e rendere lo scaffolding più controllabile partendo dai riferimenti.",
  "home.roadmap.phase4.title": "Creare il framework base di StealThis",
  "home.roadmap.phase4.body":
    "Un framework semplice per progetti web, ispirato ai workflow in stile Astro e focalizzato sulla creazione assistita dall'AI.",
  "home.keywords.eyebrow": "Linguaggio del progetto",
  "home.keywords.title": "Le parole che definiscono questo progetto",
  "home.keywords.lead":
    "Non sono termini di marketing. Sono principi operativi su come costruiamo, condividiamo e rilasciamo software con meno complessità e più ownership.",
  "home.keywords.aria": "Parole chiave del progetto e significati",
  "home.keywords.control.word": "CONTROLLO",
  "home.keywords.control.accent": "Controllo",
  "home.keywords.control.text":
    "significa scegliere il tuo stack, il tuo sistema di stile e il tuo ritmo di delivery senza rimanere bloccato in default rigidi.",
  "home.keywords.reference.word": "RIFERIMENTO",
  "home.keywords.reference.accent": "Riferimento",
  "home.keywords.reference.text":
    "significa imparare da implementazioni concrete, non da thread astratti dispersi in fonti scollegate.",
  "home.keywords.reuse.word": "RIUSO",
  "home.keywords.reuse.accent": "Riuso",
  "home.keywords.reuse.text":
    "è il default. Parti da una base comprovata, adattala e investi energia nella differenziazione invece che nella ripetizione.",
  "home.keywords.collaboration.word": "COLLABORAZIONE",
  "home.keywords.collaboration.accent": "Collaborazione",
  "home.keywords.collaboration.text":
    "significa umani e bot che costruiscono dallo stesso contesto, convenzioni e riferimenti di produzione.",
  "home.keywords.practice.word": "PRATICA",
  "home.keywords.practice.accent": "Pratica",
  "home.keywords.practice.text":
    "è dove emerge la qualità: workflow ripetibili, pattern testati e disciplina di implementazione.",
  "home.keywords.ownership.word": "OWNERSHIP",
  "home.keywords.ownership.accent": "Ownership",
  "home.keywords.ownership.text":
    "significa capire cosa esegui, perché funziona e come evolverlo quando i requisiti cambiano.",
  "home.keywords.clarity.word": "CHIAREZZA",
  "home.keywords.clarity.accent": "Chiarezza",
  "home.keywords.clarity.text":
    "rimuove attrito: un posto per i riferimenti, un linguaggio per le decisioni, un percorso dall'idea alla consegna.",
  "home.keywords.ship.word": "RILASCIA",
  "home.keywords.ship.accent": "Rilascia",
  "home.keywords.ship.text":
    "significa arrivare in produzione prima senza abbassare gli standard di architettura, accessibilità e manutenibilità.",
  "home.scramble.eyebrow": "Filosofia Steal This",
  "home.scramble.title": "Parole che riveliamo mentre costruiamo",
  "home.scramble.lead":
    "Ogni riga qui sotto è un impegno verso un modo più pratico di costruire software: riferimenti solidi, contesto condiviso ed esecuzione più veloce con controllo.",
  "home.scramble.phrases":
    "STEAL THIS →||COSTRUISCI CON CONTROLLO||PARTI DAI RIFERIMENTI||UMANI + BOT||MENO ATTRITO, PIÙ DELIVERY",
