  "home.manifesto.eyebrow": "Buduj z kontrolą",
  "home.manifesto.title": "Bierz to, co działa. Dostarczaj to, czego chcesz.",
  "home.manifesto.lead": "Dla ludzi i botów, którzy chcą budować software bez zaczynania od zera.",
  "home.manifesto.body1":
    "StealThis to biblioteka oparta na referencjach. Przeglądaj każdy element, rozumiej jak działa i wykorzystuj go we własnym stacku. Mniej fragmentacji, mniej złożoności i więcej kontroli nad systemem stylów oraz narzędziami, z którymi budujesz.",
  "home.manifesto.body2":
    "Cel jest prosty: jedno wspólne miejsce, gdzie spotykają się wiedza, sprawdzone praktyki i referencje gotowe do produkcji. Wybierasz bazę, dostosowujesz ją i idziesz dalej bez ciągłego odbudowywania fundamentów.",
  "home.manifesto.howToTitle": "Jak korzystać z tego miejsca",
  "home.manifesto.howToAria": "Jak korzystać z tego miejsca",
  "home.manifesto.step1.accent": "Znajdź referencję",
  "home.manifesto.step1.text": "która już rozwiązuje część Twojego problemu.",
  "home.manifesto.step2.accent": "Przeanalizuj szybko:",
  "home.manifesto.step2.text": "strukturę, zachowanie i szczegóły implementacji.",
  "home.manifesto.step3.accent": "Dostosuj",
  "home.manifesto.step3.text": "do swojego systemu stylów, stacku i ograniczeń.",
  "home.manifesto.step4.accent": "Wdrażaj szybciej",
  "home.manifesto.step4.text": "bez poświęcania jakości kodu.",
  "home.manifesto.micro": "Mniej boilerplate. Mniej przełączania kontekstu. Więcej budowania.",
  "home.manifesto.practiceTitle": "Co zyskujesz w praktyce",
  "home.manifesto.practiceBody":
    "Dostajesz szybszą pierwszą wersję, mocniejsze referencje implementacyjne i mniej ślepych startów. Zamiast sklejać kontekst z dziesięciu źródeł, pracujesz z jednego miejsca i poruszasz się świadomie.",
  "home.manifesto.outcomesAria": "Praktyczne efekty",
  "home.manifesto.outcomeA.accent": "Szybkość z kontrolą:",
  "home.manifesto.outcomeA.text": "zaczynaj od realnej bazy i trzymaj własne standardy.",
  "home.manifesto.outcomeB.accent": "Wspólny język:",
  "home.manifesto.outcomeB.text": "ludzie i boty pracują na tych samych referencjach.",
  "home.manifesto.outcomeC.accent": "Kumulacja wiedzy:",
  "home.manifesto.outcomeC.text": "każde ponowne użycie ułatwia kolejną budowę.",
  "home.manifesto.future":
    "Kierunek na przyszłość: własne systemy wizualne, własne konfiguracje workflow i tworzenie oprogramowania z dowolnego miejsca według własnych zasad.",
  "home.roadmap.eyebrow": "Roadmap w toku",
  "home.roadmap.title": "Od fundamentów do frameworka webowego AI-first",
  "home.roadmap.lead":
    "Budujemy to publicznie, krok po kroku. Droga zaczyna się od mocnych fundamentów, potem jakości dokumentacji, następnie workflow generowania projektów, a na końcu lekkiego frameworka do tworzenia web software z wsparciem AI.",
  "home.roadmap.dot.foundation": "Fundament",
  "home.roadmap.dot.docs": "Jakość docs",
  "home.roadmap.dot.builder": "Builder",
  "home.roadmap.dot.framework": "Framework",
  "home.roadmap.phase1.title": "Zbuduj fundament",
  "home.roadmap.phase1.body":
    "Ustabilizuj bazową architekturę, kluczowe strony, wielokrotnego użytku prymitywy i język wizualny.",
  "home.roadmap.phase2.title": "Ulepsz docs zgodnie z best practices",
  "home.roadmap.phase2.body":
    "Spraw, by wskazówki były jaśniejsze, praktyczne i wykonalne, aby wdrażać szybciej i z mniejszym zamieszaniem.",
  "home.roadmap.phase3.title": "Ulepsz builder do tworzenia projektów",
  "home.roadmap.phase3.body":
    "Zmniejsz tarcie na etapie setupu i zwiększ kontrolę nad scaffoldingiem opartym o referencje.",
  "home.roadmap.phase4.title": "Stwórz podstawowy framework StealThis",
  "home.roadmap.phase4.body":
    "Prosty framework dla projektów webowych, inspirowany workflow w stylu Astro i skupiony na tworzeniu wspieranym przez AI.",
  "home.keywords.eyebrow": "Język projektu",
  "home.keywords.title": "Słowa, które definiują ten projekt",
  "home.keywords.lead":
    "To nie są hasła marketingowe. To zasady operacyjne tego, jak budujemy, udostępniamy i dostarczamy software z mniejszą złożonością i większą odpowiedzialnością.",
  "home.keywords.aria": "Słowa kluczowe projektu i znaczenia",
  "home.keywords.control.word": "KONTROLA",
  "home.keywords.control.accent": "Kontrola",
  "home.keywords.control.text":
    "oznacza wybór własnego stacku, systemu stylów i tempa dostarczania bez zamknięcia w sztywnych domyślnych ustawieniach.",
  "home.keywords.reference.word": "REFERENCJA",
  "home.keywords.reference.accent": "Referencja",
  "home.keywords.reference.text":
    "oznacza naukę z konkretnych implementacji, a nie z abstrakcyjnych wątków rozproszonych po odłączonych źródłach.",
  "home.keywords.reuse.word": "PONOWNE UŻYCIE",
  "home.keywords.reuse.accent": "Ponowne użycie",
  "home.keywords.reuse.text":
    "to domyślne podejście. Zacznij od sprawdzonej bazy, dostosuj ją i inwestuj energię w różnicowanie zamiast powtarzania.",
  "home.keywords.collaboration.word": "WSPÓŁPRACA",
  "home.keywords.collaboration.accent": "Współpraca",
  "home.keywords.collaboration.text":
    "oznacza, że ludzie i boty budują z tego samego kontekstu, konwencji i referencji produkcyjnych.",
  "home.keywords.practice.word": "PRAKTYKA",
  "home.keywords.practice.accent": "Praktyka",
  "home.keywords.practice.text":
    "to miejsce, gdzie rodzi się jakość: powtarzalne workflow, sprawdzone wzorce i dyscyplina implementacji.",
  "home.keywords.ownership.word": "ODPOWIEDZIALNOŚĆ",
  "home.keywords.ownership.accent": "Odpowiedzialność",
  "home.keywords.ownership.text":
    "oznacza rozumienie tego, co uruchamiasz, dlaczego to działa i jak to rozwijać, gdy zmieniają się wymagania.",
  "home.keywords.clarity.word": "JASNOŚĆ",
  "home.keywords.clarity.accent": "Jasność",
  "home.keywords.clarity.text":
    "usuwa tarcie: jedno miejsce na referencje, jeden język decyzji i jedna ścieżka od pomysłu do dostarczenia.",
  "home.keywords.ship.word": "DOSTARCZAJ",
  "home.keywords.ship.accent": "Dostarczaj",
  "home.keywords.ship.text":
    "oznacza szybsze wejście na produkcję bez obniżania standardów architektury, dostępności i utrzymywalności.",
  "home.scramble.eyebrow": "Filozofia Steal This",
  "home.scramble.title": "Słowa, które ujawniamy podczas budowy",
  "home.scramble.lead":
    "Każda linia poniżej to zobowiązanie do bardziej praktycznego sposobu budowania software: mocne referencje, wspólny kontekst i szybsza egzekucja z kontrolą.",
  "home.scramble.phrases":
    "STEAL THIS →||BUDUJ Z KONTROLĄ||STARTUJ Z REFERENCJI||LUDZIE + BOTY||MNIEJ TARCIA, WIĘCEJ DOSTARCZANIA",
