  "collection.wiki.title": "الويكي وقواعد المعرفة",
  "collection.wiki.desc": "مقالات ويكي وصفحات توثيق ومراجع API ودروس، ومكوّنات معرفية قابلة لإعادة الاستخدام (صندوق معلومات، فهرس محتويات ثابت، شجرة توثيق، تنبيهات، مبدّل إصدارات، سجل مراجعات، حواشٍ)، وبحث موجّه وأمر Command-K، ومحرر مقالات ولوحة تحكم لقاعدة المعرفة، إضافة إلى صفحات هبوط بطابع موسوعة/توثيق مطورين/فاندوم/دليل عمل/دعم.",
